import React from "react";
import '../App.css';
import '../global'
import HomeApiRerA from '../API/HomeApiRerA';



class Home extends React.Component{

    state = {
        APIKEY
      };

      
    handleChange(event) {
        var value = event.target.value;
        global.key.name = event.target.value;
        this.setState({
            value
        });
      }
render(){
    return(
        <div className="Mid">
            <div className="Col80">
                <h2>Horaires des prochains départs</h2>
                <br/>
                <HomeApiRerA APIKEY={global.key.name}/>
            </div>
            <div className="Col20">
                <div className ="Col201">
                Entrer la nouvelle clé API :
                <input type="text" value={global.key.name}
                onChange={event => this.handleChange(event)}
                />
            </div>
            <div className="Col202">
                    <h3>Incidents signalés</h3>
                    Aucun incident n'a été signalé sur votre ligne
                </div>   
            </div>    
    </div>
    )
}
}

export default Home
